name: Sanitizers

# Memory-safety / leak guardrail: runs the pure-Rust core test suite under
# AddressSanitizer (ASan, which embeds LeakSanitizer) so a genuine leak or
# use-after-free in the protocol core fails the build.
#
# Scope: ONLY `mesh-talk-core --lib` (the UI-free core). The Tauri app links
# GTK/WebKit C libraries whose internals trip ASan with false positives we can't
# fix from here, so the app is deliberately excluded.
#
# Run on PRs targeting main so branch protection can require this memory-safety
# check before merge. Run again on main so the README badge reflects the merged
# code; keep the weekly run to catch toolchain and dependency drift.
# ASan needs the nightly toolchain + `-Z build-std` (a full std rebuild).
on:
  merge_group:
    types: [checks_requested]
  pull_request:
    branches: [main]
  push:
    branches: [main]
  schedule:
    - cron: "0 6 * * 1" # Mondays 06:00 UTC
  workflow_dispatch:

# Read-only: just checks out and runs the test suite under the sanitizer.
permissions:
  contents: read

env:
  CARGO_TERM_COLOR: always
  # Upgrade through a reviewed PR with all eight native instrumentation controls.
  MESH_ASAN_TOOLCHAIN: nightly-2026-11-07
  RUSTFLAGS: "-Zsanitizer=address"
  RUSTDOCFLAGS: "-Zsanitizer=address"
  ASAN_OPTIONS: "detect_leaks=1"
  RUST_TEST_THREADS: "1"

concurrency:
  group: ${{ github.workflow }}-${{ github.event_name }}-${{ github.event.pull_request.number || github.ref }}-${{ github.event_name == 'push' && github.run_id || 'candidate' }}
  cancel-in-progress: ${{ github.event_name == 'pull_request' || github.event_name == 'merge_group' }}

jobs:
  scope:
    uses: ./.github/workflows/ci-scope.yml

  cohort:
    if: needs.scope.outputs.full == 'true'
    needs: [scope]
    name: Build ASan test archive
    runs-on: ubuntu-latest
    outputs:
      toolchain: ${{ steps.cohort.outputs.toolchain }}
      rustc: ${{ steps.cohort.outputs.rustc }}
      cargo: ${{ steps.cohort.outputs.cargo }}
      archive_sha256: ${{ steps.build.outputs.archive_sha256 }}
      manifest_sha256: ${{ steps.build.outputs.manifest_sha256 }}
      artifact_id: ${{ steps.archive.outputs.artifact-id }}
    steps:
      - name: Checkout
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 22
      - name: Prepare hosted Linux build storage
        id: runner_storage
        if: runner.os == 'Linux'
        shell: bash
        run: sudo --preserve-env=GITHUB_ACTIONS,RUNNER_ENVIRONMENT,RUNNER_OS "$(command -v node)" scripts/ci/runner-storage.mjs --prepare | tee "$RUNNER_TEMP/runner-storage.json"

      - name: Preserve runner storage measurements
        if: always() && steps.runner_storage.outcome == 'success'
        continue-on-error: true
        uses: actions/upload-artifact@v7
        with:
          name: runner-storage-${{ github.job }}-${{ strategy.job-index || 0 }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/runner-storage.json
          if-no-files-found: error
          retention-days: 14

      - name: Install configured nightly cohort
        uses: dtolnay/rust-toolchain@nightly
        with:
          toolchain: ${{ env.MESH_ASAN_TOOLCHAIN }}
          components: rust-src
      - name: Publish exact installed nightly cohort
        id: cohort
        run: node scripts/ci/asan.mjs cohort
      - name: Cache Rust build
        uses: Swatinem/rust-cache@v2
        with:
          save-if: ${{ github.ref == 'refs/heads/main' }}
          # Preserve the compatible cache prefix after moving compilation jobs.
          shared-key: sanitizers-shards
      - name: Install pinned Nextest
        uses: taiki-e/install-action@v2.90.3
        with:
          tool: cargo-nextest@0.9.150
          fallback: none
      - name: Verify pinned ASan archive protocol
        run: node --test scripts/ci/asan-cli.test.mjs
      - name: Compile and seal the ASan core archive once
        id: build
        env:
          # Bound compiler and LLVM jobserver work after restoring the same cache.
          CARGO_BUILD_JOBS: "2"
          MESH_ASAN_TOOLCHAIN: ${{ steps.cohort.outputs.toolchain }}
          MESH_ASAN_RUSTC: ${{ steps.cohort.outputs.rustc }}
          MESH_ASAN_CARGO: ${{ steps.cohort.outputs.cargo }}
        run: node scripts/ci/asan.mjs build tmp/asan-build
      - name: Preserve ASan build diagnostics
        if: always()
        continue-on-error: true
        uses: actions/upload-artifact@v7
        with:
          name: asan-build-diagnostics-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}
          path: tmp/asan-build-diagnostics/
          if-no-files-found: warn
          retention-days: 7
      - name: Upload this attempt's compiled ASan archive
        id: archive
        uses: actions/upload-artifact@v7
        with:
          name: asan-build-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}
          path: tmp/asan-build/
          compression-level: 0
          if-no-files-found: error
          retention-days: 1

  shards:
    if: needs.scope.outputs.full == 'true'
    name: ASan core shard (${{ matrix.shard }}/8)
    needs: [cohort, scope]
    runs-on: ubuntu-latest
    strategy:
      fail-fast: false
      matrix:
        shard: [1, 2, 3, 4, 5, 6, 7, 8]
    env:
      MESH_ASAN_TOOLCHAIN: ${{ needs.cohort.outputs.toolchain }}
      MESH_ASAN_RUSTC: ${{ needs.cohort.outputs.rustc }}
      MESH_ASAN_CARGO: ${{ needs.cohort.outputs.cargo }}
      MESH_ASAN_ARCHIVE_SHA256: ${{ needs.cohort.outputs.archive_sha256 }}
      MESH_ASAN_MANIFEST_SHA256: ${{ needs.cohort.outputs.manifest_sha256 }}
      # Keep production case budgets and one instrumented test per runner.
    steps:
      - name: Checkout
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 22
      - name: Install exact nightly cohort
        uses: dtolnay/rust-toolchain@nightly
        with:
          toolchain: ${{ needs.cohort.outputs.toolchain }}
          components: rust-src
      - name: Install pinned Nextest
        uses: taiki-e/install-action@v2.90.3
        with:
          tool: cargo-nextest@0.9.150
          fallback: none
      - name: Download the current compiled ASan archive
        uses: actions/download-artifact@v8
        with:
          artifact-ids: ${{ needs.cohort.outputs.artifact_id }}
          path: tmp/asan-build
      # Both controls use the same instrumented std target as the real core.
      # A genuine ASan diagnosis must fail the intentional use-after-free.
      - name: Prove actual AddressSanitizer instrumentation
        run: node scripts/ci/asan.mjs smoke tmp/asan-evidence
      - name: Test serial ASan partition
        env:
          MESH_ASAN_SHARD: ${{ matrix.shard }}
        run: node scripts/ci/asan.mjs shard "$MESH_ASAN_SHARD" tmp/asan-evidence
      - name: Preserve ASan inventory and raw execution evidence
        if: always()
        uses: actions/upload-artifact@v7
        with:
          name: asan-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}-shard-${{ matrix.shard }}
          path: tmp/asan-evidence/
          if-no-files-found: error

  asan:
    name: ASan + LeakSanitizer (core)
    needs: [cohort, shards, scope]
    if: ${{ !cancelled() }}
    runs-on: ubuntu-latest
    env:
      MESH_ASAN_TOOLCHAIN: ${{ needs.cohort.outputs.toolchain }}
      MESH_ASAN_RUSTC: ${{ needs.cohort.outputs.rustc }}
      MESH_ASAN_CARGO: ${{ needs.cohort.outputs.cargo }}
      MESH_ASAN_ARCHIVE_SHA256: ${{ needs.cohort.outputs.archive_sha256 }}
      MESH_ASAN_MANIFEST_SHA256: ${{ needs.cohort.outputs.manifest_sha256 }}
      MESH_ASAN_SHARDS_RESULT: ${{ needs.shards.result }}
      MESH_ASAN_BUILD_RESULT: ${{ needs.cohort.result }}
    steps:
      - name: Checkout
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 2
      - id: scope
        uses: ./.github/actions/ci-scope
        with:
          full: ${{ needs.scope.outputs.full }}
          upstream_result: ${{ needs.scope.result }}
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        if: ${{ steps.scope.outputs.full == 'true' }}
        with:
          node-version: 22
      - name: Download this attempt's ASan evidence
        if: ${{ steps.scope.outputs.full == 'true' }}
        uses: actions/download-artifact@v8
        with:
          pattern: asan-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}-shard-*
          path: tmp/asan-union
      - name: Verify every actual shard and complete exact-source union
        if: ${{ steps.scope.outputs.full == 'true' }}
        run: node scripts/ci/asan.mjs verify tmp/asan-union
#!/usr/bin/env node
// One compiled archive, eight serial ASan partitions and exact union evidence.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { createReadStream, existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync, appendFileSync, openSync, readSync, closeSync, statfsSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { command as runLogged, inventory, verifyPartition, verifyExecution, versions } from "./windows-coverage.mjs";

// Observe only fixed kernel counters, never process arguments or environment dumps.
// This adds evidence; it cannot qualify an archive or change the compiler result.
function kernelCounters(file, select) {
  let descriptor;
  try {
    descriptor = openSync(file, "r");
    const bytes = Buffer.alloc(16384);
    const count = readSync(descriptor, bytes, 0, bytes.length, 0);
    return { values: bytes.subarray(0, count).toString("utf8").split("\n").filter(select), truncated: count === bytes.length };
  } catch (error) { return { error: error.code ?? "unavailable" }; }
  finally { if (descriptor !== undefined) closeSync(descriptor); }
}
export function buildResourceSample() {
  const disk = statfsSync(process.cwd());
  return {
    memory: { totalBytes: os.totalmem(), freeBytes: os.freemem() },
    loadAverage: os.loadavg(), cpuCount: os.availableParallelism(),
    diskAvailableBytes: disk.bavail * disk.bsize,
    ...(process.platform === "linux" ? {
      meminfo: kernelCounters("/proc/meminfo", line => /^(MemTotal|MemAvailable|SwapTotal|SwapFree|Dirty|Writeback):/u.test(line)),
      vmstat: kernelCounters("/proc/vmstat", line => /^(oom_kill|pswpin|pswpout) /u.test(line)),
      pressure: kernelCounters("/proc/pressure/memory", line => /^(some|full) /u.test(line)),
      rootCgroupEvents: kernelCounters("/sys/fs/cgroup/memory.events", line => /^(low|high|max|oom|oom_kill|oom_group_kill) /u.test(line)),
      rootCgroupCurrent: kernelCounters("/sys/fs/cgroup/memory.current", line => /^\d+$/u.test(line)),
      rootCgroupMax: kernelCounters("/sys/fs/cgroup/memory.max", line => /^(max|\d+)$/u.test(line)),
    } : {}),
  };
}
export async function observeBuild(directory, work, { sample = buildResourceSample, intervalMs = 30000, maxSamples = 720, emit = row => console.log(`ASan build resource: ${JSON.stringify(row)}`) } = {}) {
  assert.ok(Number.isInteger(intervalMs) && intervalMs > 0, "Invalid ASan sample interval");
  assert.ok(Number.isInteger(maxSamples) && maxSamples > 0 && maxSamples <= 720, "Invalid ASan sample limit");
  const started = performance.now();
  let count = 0, timer, outcome = "failure", file, fileError;
  try { mkdirSync(directory, { recursive: true }); file = openSync(path.join(directory, "resources.jsonl"), "wx"); } catch (error) { fileError = error.code ?? "unavailable"; }
  const record = data => {
    const row = { ...(fileError ? { fileError } : {}), at: new Date().toISOString(), elapsedMs: Math.round(performance.now() - started), ...data };
    // Fixed observations are small; retain an explicit omission if that changes.
    const bounded = Buffer.byteLength(JSON.stringify(row)) <= 8192 ? row : { at: row.at, event: "diagnostic-error", error: "sample-too-large" };
    try { if (file !== undefined) appendFileSync(file, JSON.stringify(bounded) + "\n"); } catch (error) { bounded.fileError = fileError = error.code ?? "unavailable"; }
    try { emit(bounded); } catch { /* A closed diagnostic sink cannot certify or fail compilation. */ }
  };
  const tick = () => {
    count++;
    try { record({ event: "sample", ...sample() }); }
    catch (error) { record({ event: "sample", error: error.code ?? "unavailable" }); }
    if (count >= maxSamples) { clearInterval(timer); record({ event: "limit", samples: count }); }
  };
  try {
    timer = setInterval(tick, intervalMs);
    timer.unref();
    tick();
    const result = await work();
    outcome = "success";
    return result;
  } finally {
    clearInterval(timer);
    record({ event: "finished", outcome, samples: count });
    if (file !== undefined) try { closeSync(file); } catch { /* Best-effort diagnostics only. */ }
  }
}

const partitions = [1, 2, 3, 4, 5, 6, 7, 8];
// Fixed measured outliers, not a timing database. Names must remain exact and
// default runnable in the full archive inventory before sealing or execution.
export const reservedCohorts = Object.freeze([
  Object.freeze(["node::account_documents::tests::group_inventory_long_canonical_names_fit_payload_budget_and_preserve_required_members"]),
  Object.freeze([
    "node::account_documents::tests::inventory_causality::group_inventory_directory_known_unavailable_source_can_be_acknowledged_by_another_source",
    "node::account_documents::tests::group_control_unavailable_obsolete_cache_cannot_orphan_a_large_negative_head",
    "node::account_documents::tests::group_control_normal_authorization_history_growth_keeps_bounded_current_heads",
  ]),
]);
const exactTests = names => names.map(name => `test(=${name})`).join(" or ");
export function verifyReservedInventory(full) {
  for (const name of reservedCohorts.flat()) {
    const matches = full.filter(row => row.eventName.slice(row.eventName.indexOf("$") + 1) === name);
    assert.equal(matches.length, 1, `ASan reserved test missing or ambiguous: ${name}`);
    assert.ok(matches[0].selected && !matches[0].ignored, `ASan reserved test is not default runnable: ${name}`);
  }
}
const target = "x86_64-unknown-linux-gnu";
const config = ".config/nextest-asan.toml";
const hash = value => createHash("sha256").update(value).digest("hex");
const read = file => JSON.parse(readFileSync(file, "utf8"));
const write = (file, value) => writeFileSync(file, `${JSON.stringify(value, null, 2)}\n`);
const digest = value => hash(JSON.stringify(value));

export function nightlyFromManifest(text) {
  const header = text.split(/^\[/mu)[0];
  const dates = [...header.matchAll(/^date\s*=\s*"(\d{4}-\d{2}-\d{2})"\s*$/gmu)];
  assert.equal(dates.length, 1, "Installed nightly manifest date is missing or ambiguous");
  const date = dates[0][1];
  const instant = new Date(`${date}T00:00:00Z`);
  assert.ok(Number.isFinite(instant.getTime()), "Invalid nightly manifest date");
  assert.equal(instant.toISOString().slice(0, 10), date, "Invalid nightly manifest date");
  return `nightly-${date}`;
}

export function partitionArgs(mode, buildArgs, shard) {
  assert.ok(["list", "run"].includes(mode), "Invalid ASan command mode");
  assert.ok(shard === undefined || partitions.includes(shard), "Invalid ASan partition");
  return ["nextest", mode, ...buildArgs, "--config-file", path.resolve(config), "--user-config-file", "none", "--profile", "default", ...(shard === undefined ? [] : shard <= 6 ? ["--partition", `hash:${shard}/6`, "-E", `not (${exactTests(reservedCohorts.flat())})`] : ["-E", `(${exactTests(reservedCohorts[shard - 7])})`]), ...(mode === "list" ? ["--message-format", "json"] : ["--test-threads", "1", "--retries", "0", "--no-fail-fast", "--no-tests", "fail", "--message-format", "libtest-json-plus", "--message-format-version", "0.1"])];
}

export function verifyAsanUnion(bundles, expected) {
  assert.equal(bundles.length, partitions.length, "Expected exactly eight ASan partitions");
  assert.deepEqual(bundles.map(bundle => bundle.receipt.shard).sort(), partitions, "Duplicate or missing ASan partition");
  const full = bundles[0].full;
  verifyReservedInventory(full);
  for (const bundle of bundles) {
    const { receipt, selected, execution } = bundle;
    assert.equal(receipt.schema, 1, "Unsupported ASan receipt");
    assert.deepEqual(receipt.identity, expected, "ASan source/run/toolchain/config identity mismatch");
    assert.deepEqual(bundle.full, full, "ASan full inventory differs across runners");
    assert.equal(digest(bundle.full), receipt.fullSha256, "ASan full inventory digest mismatch");
    assert.equal(digest(selected), receipt.selectedSha256, "ASan selected inventory digest mismatch");
    assert.equal(hash(execution), receipt.executionSha256, "ASan execution digest mismatch");
  }
  verifyPartition(full, bundles.map(bundle => bundle.selected), partitions.length);
  let executedTests = 0;
  for (const { receipt, selected, execution } of bundles) {
    verifyExecution(execution, selected);
    const count = selected.filter(row => row.selected).length;
    assert.equal(receipt.executedTests, count, "ASan execution count mismatch");
    executedTests += count;
  }
  return { totalTests: full.length, executedTests, ignoredTests: full.filter(row => row.ignored).length, shards: partitions.length };
}

// Exported for the real stable-toolchain protocol fixture. Hosted CLI callers use
// the sealed producer archive and verified runtime identity below, never test flags.
export async function runPartition(shard, directory, { buildArgs, identity, expectedInventory, cargoPrefix = [], env = process.env, afterExecution = async () => {} } = {}) {
  assert.ok(partitions.includes(shard), "Invalid ASan partition");
  mkdirSync(directory, { recursive: true });
  assert.ok(!existsSync(path.join(directory, "receipt.json")), "Prior ASan receipt cannot be reused");
  const run = (mode, index, phase) => runLogged([...cargoPrefix, ...partitionArgs(mode, buildArgs, index)], { env: { ...env, RUST_TEST_THREADS: "1", NEXTEST_EXPERIMENTAL_LIBTEST_JSON: "1" }, receipt: path.join(directory, phase), progress: path.join(directory, "progress.jsonl"), phase, liveStdout: mode === "run" });
  const full = inventory(JSON.parse(await run("list", undefined, "inventory-all")));
  if (expectedInventory) assert.deepEqual(full, expectedInventory, "ASan archive inventory differs from producer");
  verifyReservedInventory(full);
  const selected = inventory(JSON.parse(await run("list", shard, "inventory-selected")));
  assert.ok(full.every(row => row.selected === !row.ignored), "ASan full inventory has hidden filters");
  assert.deepEqual(selected.map(({ selected: _selected, ...row }) => row), full.map(({ selected: _selected, ...row }) => row), "ASan partition inventory drift");
  assert.ok(selected.some(row => row.selected), "Empty runnable ASan partition");
  write(path.join(directory, "full.json"), full);
  write(path.join(directory, "selected.json"), selected);
  const execution = await run("run", shard, "execution");
  verifyExecution(execution, selected);
  await afterExecution();
  const receipt = { schema: 1, shard, identity, fullSha256: digest(full), selectedSha256: digest(selected), executionSha256: hash(execution), executedTests: selected.filter(row => row.selected).length };
  write(path.join(directory, "receipt.json"), receipt);
  return { receipt, full, selected, execution };
}

async function fileHash(file) {
  const digest = createHash("sha256");
  for await (const bytes of createReadStream(file)) digest.update(bytes);
  return digest.digest("hex");
}
function buildIdentity(identity) {
  const { archive: _archive, ...base } = identity;
  return base;
}
async function extractArchive(archive, directory, { cargoPrefix = [], env = process.env } = {}) {
  const extracted = path.join(directory, "extracted");
  assert.ok(!existsSync(extracted), "ASan extraction directory already exists");
  mkdirSync(extracted, { recursive: true });
  const binaries = JSON.parse(await runLogged([...cargoPrefix, ...partitionArgs("list", ["--archive-file", archive, "--extract-to", extracted, "--workspace-remap", process.cwd()]), "--list-type", "binaries-only"], { env }));
  const binaryFile = path.join(directory, "binaries.json");
  write(binaryFile, binaries);
  return ["--binaries-metadata", binaryFile, "--cargo-metadata", path.join(extracted, "target/nextest/cargo-metadata.json"), "--target-dir-remap", path.join(extracted, "target"), "--workspace-remap", process.cwd()];
}

// The existing ASan owner seals compilation once; consumers retain their own
// instrumentation controls and complete serial execution receipts.
export async function produceArchive(directory, { buildArgs, identity, cargoPrefix = [], env = process.env, afterBuild = async () => {}, diagnostics } = {}) {
  const archive = path.join(directory, "core.tar.zst");
  assert.ok(!existsSync(archive) && !existsSync(path.join(directory, "archive.json")), "Prior ASan archive cannot be reused");
  mkdirSync(directory, { recursive: true });
  await runLogged([...cargoPrefix, "nextest", "archive", ...buildArgs, "--config-file", path.resolve(config), "--user-config-file", "none", "--profile", "default", "--archive-file", archive], { env, liveStdout: true, ...(diagnostics ? { receipt: path.join(diagnostics, "compile"), progress: path.join(diagnostics, "progress.jsonl"), phase: "compile" } : {}) });
  const probe = path.join(directory, "probe");
  try {
    const reuse = await extractArchive(archive, probe, { cargoPrefix, env });
    const full = inventory(JSON.parse(await runLogged([...cargoPrefix, ...partitionArgs("list", reuse)], { env })));
    assert.ok(full.some(row => row.selected), "Empty ASan producer inventory");
    assert.ok(full.every(row => row.selected === !row.ignored), "ASan archive has hidden filters");
    verifyReservedInventory(full);
    await afterBuild();
    const manifest = { schema: 1, identity: buildIdentity(identity), archiveSha256: await fileHash(archive), fullSha256: digest(full), full };
    write(path.join(directory, "archive.json"), manifest);
    return { sha256: manifest.archiveSha256, manifestSha256: await fileHash(path.join(directory, "archive.json")) };
  } finally {
    rmSync(probe, { recursive: true, force: true });
  }
}

export async function verifyArchive(directory, identity) {
  assert.match(identity.archive?.sha256 ?? "", /^[a-f0-9]{64}$/u, "Missing trusted ASan archive digest");
  assert.match(identity.archive?.manifestSha256 ?? "", /^[a-f0-9]{64}$/u, "Missing trusted ASan manifest digest");
  const manifestBytes = readFileSync(path.join(directory, "archive.json"));
  assert.equal(hash(manifestBytes), identity.archive.manifestSha256, "ASan archive manifest digest mismatch");
  const manifest = JSON.parse(manifestBytes);
  assert.equal(manifest.schema, 1, "Unsupported ASan archive manifest");
  assert.deepEqual(manifest.identity, buildIdentity(identity), "ASan archive source/compiler/config identity mismatch");
  assert.equal(manifest.archiveSha256, identity.archive.sha256, "ASan producer archive digest mismatch");
  assert.equal(await fileHash(path.join(directory, "core.tar.zst")), identity.archive.sha256, "ASan archive digest mismatch");
  assert.equal(digest(manifest.full), manifest.fullSha256, "ASan producer inventory digest mismatch");
  assert.ok(manifest.full.some(row => row.selected) && manifest.full.every(row => row.selected === !row.ignored), "Invalid ASan producer inventory");
  verifyReservedInventory(manifest.full);
  return manifest;
}

export async function reuseArchive(directory, outputDirectory, identity, options = {}) {
  const manifest = await verifyArchive(directory, identity);
  // Keep disposable compiled binaries beside the evidence uploaded by callers.
  const runtimeDirectory = `${path.resolve(outputDirectory)}-archive-runtime`;
  const buildArgs = await extractArchive(path.join(directory, "core.tar.zst"), runtimeDirectory, options);
  return { buildArgs, expectedInventory: manifest.full };
}

async function output(binary, args) { return (await runLogged(args, { binary })).trim(); }

async function cohort() {
  const toolchain = process.env.MESH_ASAN_TOOLCHAIN;
  assert.match(toolchain ?? "", /^nightly-\d{4}-\d{2}-\d{2}$/u, "ASan requires a declared dated nightly toolchain");
  assert.ok(process.env.GITHUB_OUTPUT, "Cohort output requires GITHUB_OUTPUT");
  const rustc = await output("rustup", ["which", "--toolchain", toolchain, "rustc"]);
  const manifest = path.resolve(path.dirname(rustc), "../lib/rustlib/multirust-channel-manifest.toml");
  assert.equal(nightlyFromManifest(readFileSync(manifest, "utf8")), toolchain, "Installed nightly manifest differs from declared toolchain");
  const rustcSha256 = hash(await output("rustup", ["run", toolchain, "rustc", "-vV"]));
  const cargoSha256 = hash(await output("rustup", ["run", toolchain, "cargo", "-vV"]));
  appendFileSync(process.env.GITHUB_OUTPUT, `toolchain=${toolchain}\nrustc=${rustcSha256}\ncargo=${cargoSha256}\n`);
  console.log(`ASan cohort: ${toolchain} (${rustcSha256})`);
}

async function expectedIdentity() {
  assert.equal(process.platform, "linux", "Hosted ASan requires Linux");
  assert.equal(process.arch, "x64", "Hosted ASan requires x86-64");
  const { GITHUB_SHA: sourceSha, GITHUB_RUN_ID: runId, GITHUB_RUN_ATTEMPT: runAttempt, MESH_ASAN_TOOLCHAIN: toolchain, MESH_ASAN_RUSTC: rustcSha256, MESH_ASAN_CARGO: cargoSha256 } = process.env;
  assert.match(sourceSha ?? "", /^[a-f0-9]{40}$/u, "ASan requires exact workflow source SHA");
  assert.match(runId ?? "", /^[1-9]\d*$/u, "ASan requires workflow run ID");
  assert.match(runAttempt ?? "", /^[1-9]\d*$/u, "ASan requires workflow run attempt");
  assert.match(toolchain ?? "", /^nightly-\d{4}-\d{2}-\d{2}$/u, "ASan requires one dated nightly cohort");
  for (const value of [rustcSha256, cargoSha256]) assert.match(value ?? "", /^[a-f0-9]{64}$/u, "ASan requires cohort compiler fingerprints");
